function coverageFor(p,period,cutoff=st.asOf){let required=teams(get('projects',p)),map=latestInputs(p,period),ok=required.filter(t=>acceptedInput(map[t],cutoff));return{expected:required.length,accepted:ok.length,missing:required.filter(t=>!ok.includes(t))};}
function archivable(role,id){const row=get(role,id);if((['updates','deliverables'].includes(role)&&row?.data.status==='Accepted')||(role==='reports'&&row?.data.status==='Approved')||(role==='actions'&&['Approved','Rejected'].includes(row?.data.status))||role==='distributions')throw Error('Reviewed historical evidence cannot be archived');complete(...Object.keys(R));let guards={sponsors:[['projects','sponsor_id']],projects:[['milestones','project_id'],['deliverables','project_id'],['actions','project_id'],['updates','project_id'],['reports','project_id'],['distributions','project_id']],reports:[['distributions','report_id']]};for(let [target,key] of guards[role]||[])if(all(target).rows.some(x=>x.data[key]===id))throw Error('Cannot archive: linked '+target+' records exist');if(['milestones','deliverables','actions','updates'].includes(role))for(let rpt of all('reports').rows)if(rpt.data.status==='Approved'&&String(rpt.data.source_refs||'').split(/\s+/).some(v=>v.startsWith(role+':'+id+':')))throw Error('Approved sponsor report references this source record');}
function clean(role,draft,prev,mode){let d=prev?{...prev}:Object.fromEntries(R[role].map(f=>[f.key,f.kind==='boolean'?false:null]));for(let f of R[role]){if(f.key==='archived')continue;if(!Object.prototype.hasOwnProperty.call(draft,f.key))continue;let v=draft[f.key];if(v===null||v===undefined||typeof v==='string'&&!v.trim())v=null;else{if(!['string','number','boolean'].includes(typeof v))throw Error('Invalid scalar: '+f.label);if(f.kind==='boolean'){if(![true,false,'true','false'].includes(v))throw Error('Invalid boolean: '+f.label);v=bool(v);}else if(f.kind==='number'){v=num(v);if(v===null)throw Error('Invalid number: '+f.label);}else if(f.kind==='date'){if(!iso(v))throw Error('Invalid date: '+f.label);}else{if(typeof v!=='string')throw Error('Invalid text: '+f.label);v=v.trim();if(v.length>(f.key==='source_refs'?50000:f.kind==='longtext'?4000:850))throw Error('Text exceeds field limit: '+f.label);if(f.kind==='select'&&!f.options.includes(v))throw Error('Unsupported selection: '+f.label);}}if(!mp[role].writable.includes(f.key)&&(v??null)!==(prev?.[f.key]??null))throw Error('Field is not writable: '+f.label);d[f.key]=v;}
 if(mode==='create')d.archived=false;
 if(role==='milestones'&&mode==='create')d.baseline_date=d.current_date||null;
 if(role==='updates'&&mode==='create')d.revision=Number(d.revision)||1;
 if(role==='reports'&&mode==='create'){d.revision=Number(d.revision)||1;if(!d.as_of)d.as_of=st.asOf;if(!d.period_key)d.period_key=st.period;if(covered('projects','milestones','deliverables','actions','updates')&&d.project_id){d.source_digest=sourceSignature(d.project_id,d.period_key,d.as_of);d.source_refs=sourceIds(d.project_id,d.period_key,d.as_of);let cv=coverageFor(d.project_id,d.period_key,d.as_of);d.coverage_note=cv.accepted+'/'+cv.expected+' accepted team updates';}}
 for(let f of R[role])if(f.required&&(d[f.key]===null||d[f.key]===undefined||d[f.key]===''||f.kind==='number'&&!Number.isFinite(d[f.key])))throw Error('Required: '+f.label);
 if(d.project_id&&st.projectId&&d.project_id!==st.projectId&&role!=='projects'&&mode==='create')throw Error('Cannot create outside selected project');
 return d;}
function createProposal(ed){if(!can(ed.role))throw Error('Authorized write permission unavailable');let prev=null;if(ed.mode==='edit'){let current=get(ed.role,ed.id);if(!current||current.version!==ed.baseVersion)throw Error('Conflict: original record changed or access was removed; draft retained');prev=current.data;}
 let d=clean(ed.role,ed.draft,prev,ed.mode);guard(ed.role,d,prev,ed.id);
 if(ed.mode==='create'&&R[ed.role].some(f=>!mp[ed.role].fields[f.key]||!mp[ed.role].writable.includes(f.key)))throw Error('Creation requires every approved field write binding');if(ed.role==='reports'&&String(d.source_refs||'').length>50000)throw Error('Report source references exceed 50,000 characters; narrow the authorized report dataset');let data={};for(let f of R[ed.role])if(mp[ed.role].fields[f.key]&&mp[ed.role].writable.includes(f.key))data[mp[ed.role].fields[f.key]]=d[f.key]===undefined?null:d[f.key];
 if(ed.mode==='edit')return{kind:'update_record',recordId:ed.id,expectedVersion:ed.baseVersion,data};return{kind:'create_record',typeId:mp[ed.role].typeId,data};}
function propose(changes){tools.call('records.propose',changes);st.notice='Change submitted for TrialAgents review. Nothing is saved until approved in the host.';}
function defaultDraft(role){let d={};for(let f of R[role]){if(f.kind==='select'&&f.required)d[f.key]=f.options[0];if(f.kind==='boolean')d[f.key]=false;}
 if(role==='projects')d.expected_teams='Clinical Operations|Data Management|Regulatory';
 if(role==='milestones'||role==='deliverables'||role==='actions'||role==='updates'||role==='reports'||role==='distributions')d.project_id=st.projectId||'';
 if(role==='milestones'){d.current_date=st.asOf;d.status='Planned';}
 if(role==='deliverables'){d.due_date=st.asOf;}
 if(role==='updates'){d.period_key=st.period;d.revision=1;d.status='Draft';}
 if(role==='reports'){d.period_key=st.period;d.as_of=st.asOf;d.revision=1;d.status='Draft';}
 if(role==='distributions')d.sent_date=st.asOf;
 return d;}
function copied(role,old){let d={...old,name:(old.name||'Entry')+' · revised'};delete d.archived;
 if(role==='sponsors')d.sponsor_code='';if(role==='projects')d.project_code='';
 if(role==='milestones'){d.actual_date=null;d.baseline_date=null;d.evidence_ref=null;d.status='Planned';}
 if(role==='deliverables'){d.status='Planned';d.accepted_at=null;d.acceptance_evidence=null;d.sponsor_feedback=null;}
 if(role==='actions'){d.status='Open';d.evidence_ref=null;d.decision_by=null;d.decision_at=null;}
 if(role==='updates'){d.revision=Number(old.revision||0)+1;d.status='Draft';d.submitted_at=null;d.reviewed_at=null;d.reviewer=null;d.source_refs=null;}
 if(role==='reports'){d.revision=Number(old.revision||0)+1;d.status='Draft';d.narrative=null;d.source_refs=null;d.source_digest=null;d.coverage_note=null;d.reviewer=null;d.reviewed_at=null;}
 if(role==='distributions'){d.confirmation_ref=null;d.sent_date=st.asOf;}
 return d;}
function openEditor(role,mode='create',id='',prefill={}){if(!R[role])throw Error('Unrecognized record type');let row=mode==='edit'||mode==='copy'?get(role,id):null;if((mode==='edit'||mode==='copy')&&!row)throw Error('Record inaccessible; reload');if(mode!=='edit'&&!can(role))throw Error('Write access unavailable');st.notice='';st.editor={role,parentVersions:{projects:versions('projects'),sponsors:versions('sponsors')},mode:mode==='copy'?'create':mode,id:mode==='edit'?id:null,baseVersion:mode==='edit'?row.version:null,draft:mode==='create'?{...defaultDraft(role),...prefill}:mode==='copy'?{...copied(role,row.data),...prefill}:{...row.data},additional:false};st.detail=null;st.del=null;}
function requestArchive(role,id){if(!can(role,['archived']))throw Error('Archive access unavailable');let row=get(role,id);if(!row)throw Error('Record missing');st.notice='';st.del={role,id,baseVersion:row.version,parentVersions:{projects:versions('projects'),sponsors:versions('sponsors')}};}
function confirmArchive(){let ed=st.del;if(!ed)throw Error('No archive selected');let current=get(ed.role,ed.id);if(!current||current.version!==ed.baseVersion)throw Error('Conflict: record changed since archive opened');if(!can(ed.role,['archived']))throw Error('Archive permission denied');archivable(ed.role,ed.id);propose([...parentGuard(ed,current.data),{kind:'update_record',recordId:ed.id,expectedVersion:ed.baseVersion,data:{[mp[ed.role].fields.archived]:true}}]);}
function fieldHtml(role,f,val){let name=esc(f.key),v=val===null||val===undefined?'':String(val),kind=f.kind;let ctrl='';
 if(kind.startsWith('relation-')){let rr=kind.slice(9),list=all(rr);ctrl='<select name="'+name+'" data-ui-state="true" data-action="field:'+name+'" '+(f.required?'required':'')+'><option value="">Select '+esc(f.label)+'</option>'+list.rows.map(r=>'<option value="'+esc(r.id)+'" '+(r.id===v?'selected':'')+'>'+shortText(r.data.name||r.data.project_code||r.id,60)+'</option>').join('')+'</select>';}
 else if(kind==='select')ctrl='<select name="'+name+'" data-ui-state="true" data-action="field:'+name+'">'+f.options.map(o=>'<option value="'+esc(o)+'" '+(o===v?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>';
 else if(kind==='longtext')ctrl='<textarea rows="3" name="'+name+'" data-ui-state="true" data-action="field:'+name+'" placeholder="'+esc(f.label)+'">'+esc(v)+'</textarea>';
 else if(kind==='boolean')ctrl='<input type="checkbox" name="'+name+'" data-ui-state="true" data-action="field:'+name+'" '+(bool(val)?'checked':'')+'>';
 else ctrl='<input type="'+(kind==='date'?'date':kind==='number'?'number':'text')+'" name="'+name+'" data-ui-state="true" data-action="field:'+name+'" value="'+esc(v)+'" '+(f.required?'required':'')+' '+(kind==='number'?'min="1" step="1"':'')+'>';
 return'<label class="su-field '+(kind==='longtext'?'wide':'')+'"><span>'+esc(f.label)+(f.required?' <em>*</em>':'')+'</span>'+ctrl+'</label>';}
function editor(){let ed=st.editor;if(!ed)return'';let fs=R[ed.role].filter(f=>!['archived','baseline_date'].includes(f.key)&&!(ed.role==='reports'&&['source_refs','source_digest','coverage_note'].includes(f.key))),primary=fs.filter(f=>f.required||['actual_date','current_date','status','acceptance_evidence','accepted_at','reviewer','reviewed_at','submitted_at','due_date','narrative','source_refs','source_digest','period_key','report_id','sent_date','confirmation_ref','mitigation','highlights','blockers','next_steps','decision_by','decision_at','evidence_ref','change_reason'].includes(f.key));const order=columns(ed.role);for(const list of [fs,primary])list.sort((a,b)=>(order.includes(a.key)?order.indexOf(a.key):999)-(order.includes(b.key)?order.indexOf(b.key):999));let shown=ed.additional?fs:primary;
 return'<div class="su-overlay"><aside class="su-drawer" role="dialog" aria-label="Record editor"><div class="su-drawer-head"><div><b>'+esc(ed.mode==='edit'?'Edit':'Add')+' '+esc(ed.role.replace(/s$/,''))+'</b><p>All changes require TrialAgents review</p></div>'+btn('×','cancel-editor','icon')+'</div><form data-action="save-form"><div class="su-fields">'+shown.map(f=>fieldHtml(ed.role,f,ed.draft[f.key])).join('')+'</div>'+(st.notice?'<p class="su-warning" role="alert">'+esc(st.notice)+'</p>':'')+'<div class="su-extra">'+btn(ed.additional?'Fewer fields':'Additional fields','more-fields','quiet')+'</div><div class="su-drawer-foot">'+btn('Ignore','cancel-editor','quiet')+'<button class="su-btn primary" type="submit">Review '+(ed.mode==='edit'?'changes':'new record')+'</button></div></form></aside></div>';}
function pretty(role,key,value){let f=R[role].find(x=>x.key===key);if(f?.kind.startsWith('relation-'))return label(f.kind.slice(9),value);if(f?.kind==='boolean')return bool(value)?'Yes':'No';if(value===null||value===undefined||value==='')return '—';return String(value);}
function detail(){let q=st.detail;if(!q)return'';let r=get(q.role,q.id);if(!r)return'<div class="su-overlay">'+btn('Close','close-detail')+'Record no longer available</div>';
 let extra='';if(q.role==='projects')extra='<div class="su-linked"><h3>Related work</h3>'+[['milestones','Milestones'],['deliverables','Deliverables'],['actions','Risks & actions'],['updates','Team updates'],['reports','Reports']].map(([role,t])=>'<div class="su-linkedline"><span>'+t+'</span><strong>'+all(role).rows.filter(x=>x.data.project_id===r.id).length+'</strong>'+btn('Add','prefill:'+role+':project_id:'+r.id,'link')+'</div>').join('')+'</div>';
 if(q.role==='reports'){extra='<div class="su-linked"><h3>Manual distribution history</h3><p>First 15 records; use the distribution register for full history.</p>'+all('distributions').rows.filter(x=>x.data.report_id===r.id).slice(0,15).map(x=>'<div class="su-linkedline"><span>'+esc(x.data.channel)+' · '+esc(x.data.recipient_role)+'<small>'+esc(x.data.sent_date)+'</small></span>'+btn('Open','detail:distributions:'+x.id,'link')+'</div>').join('')+(r.data.status==='Approved'?btn('Log confirmed distribution','prefill:distributions:report_id:'+r.id,'primary',!can('distributions')):'<p class="su-muted">Approve the report before logging any manual distribution.</p>')+'</div>';}
 if(q.role==='sponsors')extra='<div class="su-linked"><h3>Projects for this sponsor</h3><p>First 15 records; use Manage sponsors &amp; projects for the full directory.</p>'+all('projects').rows.filter(x=>x.data.sponsor_id===r.id).slice(0,15).map(x=>'<div class="su-linkedline"><span>'+shortText(x.data.name)+'</span>'+btn('Open','detail:projects:'+x.id,'link')+'</div>').join('')+'</div>';
 return'<div class="su-overlay"><aside class="su-drawer" role="dialog" aria-label="Record details"><div class="su-drawer-head"><div><b>'+esc(r.data.name)+'</b><p>'+esc(q.role.replace(/s$/,''))+' · reviewed source record v'+r.version+'</p></div>'+btn('×','close-detail','icon')+'</div><div class="su-detail">'+R[q.role].filter(f=>f.key!=='archived').map(f=>'<div><span>'+esc(f.label)+'</span><b>'+esc(pretty(q.role,f.key,r.data[f.key]))+'</b></div>').join('')+extra+'</div><div class="su-drawer-foot">'+btn('Copy as new version','copy:'+q.role+':'+q.id,'quiet',!can(q.role))+btn('Edit','edit:'+q.role+':'+q.id,'primary',!can(q.role))+'</div></aside></div>';}
function btn(labelN,a,cls='',disabled=false){return'<button class="su-btn '+cls+'" type="button" data-action="'+esc(a)+'" '+(disabled?'disabled':'')+'>'+labelN+'</button>';}
function chip(x){let s=String(x||'Not provided'),style=['Accepted','Approved','Achieved','Resolved'].includes(s)?'good':['Blocked','Rework','Changes requested','Overdue'].includes(s)?'bad':['Submitted','In review','High','Open'].includes(s)?'warn':'neutral';return'<span class="su-chip '+style+'">'+esc(s)+'</span>';}
function title(t,sub,extra=''){return'<div class="su-heading"><div><h1>'+esc(t)+'</h1><p>'+esc(sub)+'</p></div><div class="su-heading-side">'+extra+'</div></div>';}
function card(t,body,extra=''){return'<section class="su-card"><div class="su-card-head"><h2>'+esc(t)+'</h2>'+extra+'</div>'+body+'</section>';}
function actions(role,row){return'<span class="su-row-actions">'+btn('Open','detail:'+role+':'+row.id,'link')+btn('Edit','edit:'+role+':'+row.id,'link',!can(role))+btn('Copy','copy:'+role+':'+row.id,'link',!can(role))+btn('Archive','archive:'+role+':'+row.id,'link danger',!can(role,['archived']))+'</span>';}
function columns(role){let ordered=Array.isArray(layout.cols?.[role])?layout.cols[role].filter(k=>R[role].some(f=>f.key===k)):defaultCols[role];for(let k of defaultCols[role])if(!ordered.includes(k))ordered.push(k);let allowed=ordered.filter(k=>layout.visible?.[role+':'+k]!==false);return allowed.length?allowed:[ordered[0]];}
function table(role,opts={}){let cacheR=all(role),p=currentPage(role),pData=page(role),isAll=cacheR.complete;let rows=isAll?scope(role,cacheR.rows):scope(role,pData.rows);
 let q=String(st.query||'').trim().toLowerCase(),filter=st.filter;rows=rows.filter(x=>(!q||R[role].some(f=>String(pretty(role,f.key,x.data[f.key])).toLowerCase().includes(q)))&&(filter==='all'||x.data.status===filter||x.data.priority===filter||x.data.kind===filter));
 if(opts.filterRows)rows=rows.filter(opts.filterRows);
 rows.sort((a,b)=>String(a.data.due_date||a.data.current_date||a.data.period_key||a.data.name||'').localeCompare(String(b.data.due_date||b.data.current_date||b.data.period_key||b.data.name||'')));
 let total=isAll?rows.length:pData.total;if(isAll){p=Math.min(p,Math.max(0,Math.ceil(total/per)-1));st.pageByRole[role]=p;}let shown=isAll?rows.slice(p*per,(p+1)*per):rows,cols=columns(role),pages=Math.max(1,Math.ceil((total||0)/per));let noRows=shown.length===0?'<div class="su-empty">No '+esc(role)+' to show in this view. Add a first record or adjust the filters.</div>':'';
 return'<div class="su-table-wrap"><table class="su-table"><thead><tr>'+cols.map(k=>'<th>'+esc(R[role].find(f=>f.key===k)?.label||k)+'</th>').join('')+'<th class="su-actions-col">Actions</th></tr></thead><tbody>'+shown.map(x=>'<tr>'+cols.map(k=>'<td data-label="'+esc(R[role].find(f=>f.key===k)?.label||k)+'">'+((k==='name')?'<b>'+shortText(pretty(role,k,x.data[k]),160)+'</b>':(k==='status'||k==='priority')?chip(pretty(role,k,x.data[k])):shortText(pretty(role,k,x.data[k]),160))+'</td>').join('')+'<td data-label="Actions">'+actions(role,x)+'</td></tr>').join('')+'</tbody></table></div>'+noRows+'<div class="su-pager"><span>'+esc(isAll?'Authorized scoped records':'Page-local results · coverage incomplete')+' · '+(total===null?'count unavailable':total+' listed')+'</span><div>'+btn('Previous','page:'+role+':'+(p-1),'quiet',p===0)+ '<small>Page '+(p+1)+' of '+(isAll?pages:Math.max(pages,p+1))+'</small>'+btn('Next','page:'+role+':'+(p+1),'quiet',isAll?p>=pages-1:!(pData.raw===per&&((p+1)*per)<pData.total))+'</div></div>';}
function bar(x,n,labelN){let w=n?Math.min(100,Math.round(x/n*100)):0;return'<div class="su-bar-row"><span>'+esc(labelN)+'</span><div class="su-bar"><i style="width:'+w+'%"></i></div><b>'+(n?x+'/'+n:'—')+'</b></div>';}
function stat(labelN,value,hint,kind=''){return'<div class="su-stat '+kind+'"><span>'+esc(labelN)+'</span><strong>'+esc(value)+'</strong><small>'+esc(hint)+'</small></div>';}
function currentContext(){let candidates=all('projects').rows;let a=candidates.find(x=>x.id===st.projectId);if(!st.projectId&&candidates.length){st.projectId=candidates[0].id;a=candidates[0];}return a||null;}
function reportStats(){let p=currentContext();if(!p||!covered('projects','milestones','deliverables','actions','updates','reports'))return null;let cov=coverage();let milestones=scope('milestones',all('milestones').rows);let dlv=scope('deliverables',all('deliverables').rows);let acts=scope('actions',all('actions').rows);let dueMil=milestones.filter(x=>inPeriod(x.data.current_date)&&x.data.status!=='Cancelled');let hit=dueMil.filter(x=>x.data.status==='Achieved'&&x.data.actual_date<=x.data.current_date&&x.data.actual_date<=st.asOf);
 let dueDel=dlv.filter(x=>inPeriod(x.data.due_date)),accepted=dueDel.filter(x=>x.data.status==='Accepted'&&x.data.acceptance_evidence&&x.data.accepted_at<=st.asOf);
 let escalations=acts.filter(x=>['Open','Blocked'].includes(x.data.status)&&x.data.priority==='High');let overdue=acts.filter(x=>['Open','Blocked'].includes(x.data.status)&&iso(x.data.due_date)&&x.data.due_date<st.asOf);
 let reports=all('reports').rows.filter(x=>x.data.project_id===st.projectId&&x.data.period_key===st.period);let approved=reports.filter(x=>x.data.status==='Approved');return{cov,dueMil,hit,dueDel,accepted,escalations,overdue,reports,approved};}
function overview(){let p=currentContext(),stats=reportStats();let head=title('Sponsor overview','Reporting status, delivery changes and the decisions that need attention',btn('Manage sponsors & projects','manage','quiet'));
 if(!p)return head+warn('projects','sponsors')+card('Start here','<p class="su-muted">Create a sponsor and a project before collecting team updates.</p>'+btn('Add sponsor','add:sponsors','primary')+btn('Add project','add:projects','quiet'));
 let ready=stats&&stats.cov.expected&&stats.cov.missing.length===0;
 let cover=stats?stats.cov.accepted+'/'+stats.cov.expected:'—';let info=ready?'Team inputs complete':'Waiting for '+(stats?stats.cov.missing.length:'?')+' teams';
 let hero='<section class="su-report-hero"><div class="su-hero-left"><span class="su-eyebrow">CURRENT REPORTING PERIOD</span><strong>'+esc(st.period)+'</strong><p>'+shortText(p.data.name)+' · '+esc(p.data.cro_pm)+'</p><div class="su-hero-coverage">'+esc(info)+'</div></div><div class="su-hero-right"><span>Team updates accepted</span><b>'+esc(cover)+'</b><div class="su-hero-meter"><i style="width:'+(stats&&stats.cov.expected?Math.round(100*stats.cov.accepted/stats.cov.expected):0)+'%"></i></div>'+btn('Open team updates','nav:inputs','inverted')+'</div></section>';
 let summary='<div class="su-stats">'+stat('Milestones met on time',stats?(stats.dueMil.length?stats.hit.length+'/'+stats.dueMil.length:'—'):'—','Due in selected period')+stat('Sponsor-accepted outputs',stats?(stats.dueDel.length?stats.accepted.length+'/'+stats.dueDel.length:'—'):'—','Due in selected period')+stat('High-priority escalations',stats?stats.escalations.length:'—','Open or blocked')+stat('Approved sponsor reports',stats?stats.approved.length:'—','Selected period')+'</div>';
 let attention='';if(stats){let items=stats.cov.missing.map(t=>({name:t+' update missing',small:'Team input not accepted for '+st.period,route:'inputs',priority:'Waiting'}));for(let a of stats.overdue.slice(0,4))items.push({name:a.data.name,small:'Action due '+a.data.due_date+' · '+a.data.owner,route:'actions',priority:'Overdue'});for(let m of stats.dueMil.filter(x=>x.data.status==='Blocked').slice(0,3))items.push({name:m.data.name,small:'Blocked milestone · '+m.data.owner,route:'delivery',priority:'Blocked'});
 attention=items.slice(0,7).map(x=>'<div class="su-priority"><span class="su-prio-mark '+(x.priority==='Overdue'?'late':'')+'"></span><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.small)+'</small></div>'+chip(x.priority)+btn('Open','nav:'+x.route,'link')+'</div>').join('')||'<p class="su-empty">No missing team updates or overdue priority actions in complete authorized sources.</p>';}
 let next=stats?stats.dueMil.slice(0,5).map(x=>'<div class="su-milestone"><span>'+esc(x.data.current_date)+'</span><div><b>'+shortText(x.data.name)+'</b><small>'+esc(x.data.owner)+'</small></div>'+chip(x.data.status)+'</div>').join(''):'<p class="su-empty">Complete source access required.</p>';
 return head+warn('sponsors','projects','milestones','deliverables','actions','updates','reports')+hero+summary+'<div class="su-duo">'+card('Needs attention',attention,btn('Open risks','nav:actions','link'))+card('Milestone outlook',next||'<p class="su-empty">No milestones in this reporting period.</p>',btn('Open delivery','nav:delivery','link'))+'</div>';
}
function toolbar(role,statuses=[]){return'<div class="su-toolbar"><div class="su-search-wrap"><input aria-label="Search visible '+esc(role)+'" type="search" name="search" value="'+esc(st.query)+'" data-ui-state="true" data-action="search" placeholder="Search '+esc(role)+'"></div>'+btn('Filters','more-filters','quiet')+'<div class="su-toolbar-tail">'+btn('Add '+(role==='actions'?'item':role==='updates'?'update':role==='reports'?'report':role==='distributions'?'distribution':role.slice(0,-1)),'add:'+role,'primary',!can(role))+'</div></div>'+(st.moreFilters?'<div class="su-filters">'+btn('All','filter:all',st.filter==='all'?'active':'quiet')+statuses.map(x=>btn(esc(x),'filter:'+x,st.filter===x?'active':'quiet')).join('')+'</div>':'');}
function subs(items,current,key){return'<div class="su-subtabs" role="tablist">'+items.map(([id,t])=>btn(esc(t),'subtab:'+key+':'+id,current===id?'selected':'quiet')).join('')+'</div>';}
function delivery(){let role=st.deliveryTab,titleN=role==='milestones'?'Milestones':'Deliverables';return title('Delivery tracking','Original dates, sponsor-accepted outputs and documented changes')+subs([['milestones','Milestones'],['deliverables','Deliverables'] ],role,'deliveryTab')+warn('projects',role)+toolbar(role,role==='milestones'?['Planned','In progress','Achieved','Blocked']:['Planned','Submitted','Accepted','Rework'])+card(titleN,table(role),btn('Open project','detail:projects:'+esc(st.projectId),'link',!st.projectId));}
function actionsScreen(){return title('Risks & decisions','Operational exceptions, sponsor escalations and recorded decisions')+warn('actions','projects')+toolbar('actions',['Risk','Issue','Action','Decision','Open','Blocked','High'])+card('Action register',table('actions'));}
function inputs(){let p=currentContext(),stats=reportStats(),cv=stats?.cov||null;let rows=cv?teams().map(t=>{let record=cv.known[t];return'<div class="su-team-row"><div class="su-team-icon">'+esc(t.slice(0,1))+'</div><div><b>'+esc(t)+'</b><small>'+esc(record?'Revision '+record.data.revision+' · '+record.data.contributor:'No accepted update for this period')+'</small></div>'+chip(record?.data.status||'Not provided')+(record?btn('Review','detail:updates:'+record.id,'link'):btn('Add','prefill:updates:team:'+esc(t),'link'))+'</div>';}).join(''):'<p class="su-empty">Choose a permitted project to see expected teams.</p>';
 return title('Team updates','Collect one structured update per expected function and reporting period')+warn('projects','updates')+(cv?'<div class="su-input-summary">'+bar(cv.accepted,cv.expected,'Accepted inputs')+'<p>'+esc(cv.missing.length?cv.missing.join(' · ')+' still needed':'Every expected function has an accepted update')+'</p></div>':'')+'<div class="su-duo large-left">'+card('Contributor checklist',rows)+card('Update history',toolbar('updates',['Draft','Submitted','Accepted','Changes requested'])+table('updates'))+'</div>';
}
function reportPrompt(){let p=currentContext(),stats=reportStats();let textP='Draft a sponsor-facing CRO progress update for '+(p?.data.name||'selected project')+' for '+st.period+' using only authorized TrialAgents records for the selected project and cutoff '+st.asOf+'. Summarize accepted functional updates, milestones due versus achieved, sponsor-accepted deliverables, open high-priority risks, and decisions needed. Cite source IDs and note missing data or permissions. Do not disclose patient details, infer recruitment, claim sponsor acceptance without evidence, or send an email. Output a DRAFT only for CRO PM review.';return'<div class="su-prompt"><b>ChatGPT draft handoff</b><p>'+esc(textP)+'</p><small>Use in your connected ChatGPT conversation. This button does not execute AI or send to the sponsor.</small></div>';}
function reports(){let stat=reportStats(),cov=stat?.cov;let n=stat?.reports.length||0;let ready=!!(cov&&cov.expected&&cov.missing.length===0);
 let summary=card('Prepare sponsor report','<p class="su-muted">Prepare a source-linked draft, verify coverage, then require a second, independent human review before approval. Record any external distribution separately.</p>'+(cov?'<div class="su-briefstats">'+bar(cov.accepted,cov.expected,'Accepted teams')+'<span>Report versions this period: '+n+'</span></div>':'')+'<div class="su-briefbtns">'+btn('New report draft','add:reports','primary',!can('reports'))+btn('Show ChatGPT brief','toggle-prompt','quiet')+'</div>'+(st.showPrompt?reportPrompt():'')+(ready?'<p class="su-oknote">Source coverage is complete; approval still requires an independently reviewed current snapshot.</p>':'<p class="su-caution">Drafting is allowed, but final approval is blocked until required updates and data sources are complete.</p>'));
 let history=card('Report history — all periods',toolbar('reports',['Draft','In review','Approved'])+table('reports'));
 let dist=card('Manual distribution log','<p class="su-muted">Record who sent an approved report, when, through which manual channel, and its confirmation reference. This app sends nothing.</p>'+toolbar('distributions')+table('distributions'));
 return title('Sponsor reports','Cited drafts, independent approval and manual distribution history')+warn('projects','updates','milestones','deliverables','actions','reports','distributions')+summary+history+dist;}
function manage(){return title('Manage sponsors & projects','Maintain a reusable sponsor directory and authorized CRO project setup')+subs([['projects','Projects'],['sponsors','Sponsors']],st.manageTab,'manageTab')+warn('projects','sponsors')+toolbar(st.manageTab)+card(st.manageTab==='projects'?'Project directory':'Sponsor directory',table(st.manageTab));}
if(action==='nav:overview'||action==='nav:delivery'||action==='nav:actions'||action==='nav:inputs'||action==='nav:reports'){st.route=action.slice(4);st.query='';st.filter='all';st.moreFilters=false;}
else if(action==='manage'){st.route='manage';st.query='';st.filter='all';}
else if(action.startsWith('subtab:')){let parts=action.split(':');st[parts[1]]=parts[2];st.query='';st.filter='all';st.pageByRole={};}
else if(action==='scope-project'){st.projectId=String(ev.value||'');st.query='';st.filter='all';st.pageByRole={};st.notice='';}
else if(action==='scope-period'){let v=String(ev.value||'').trim();st.period=v;st.pageByRole={};}
else if(action==='scope-date'&&iso(ev.value)){st.asOf=ev.value;}
else if(action==='search'){st.query=String(ev.value||'');st.pageByRole={};}
else if(action==='more-filters')st.moreFilters=!st.moreFilters;
else if(action.startsWith('filter:')){st.filter=action.slice(7);st.pageByRole={};}
else if(action.startsWith('page:')){let [,role,pageN]=action.split(':');st.pageByRole[role]=Math.max(0,Number(pageN)||0);}
else if(action==='toggle-prompt')st.showPrompt=!st.showPrompt;
else if(action==='tracker:layout'){/* Native host routes this action. Preview adapter simulates reviewed persistence. */}
else if(action.startsWith('detail:')){let [,role,id]=action.split(':');st.detail={role,id};st.editor=null;}
else if(action==='close-detail')st.detail=null;
else if(action==='cancel-editor')st.editor=null;
else if(action==='more-fields'&&st.editor)st.editor.additional=!st.editor.additional;
else if(action.startsWith('add:'))openEditor(action.slice(4));
else if(action.startsWith('prefill:')){let parts=action.split(':');let role=parts[1],key=parts[2],id=parts.slice(3).join(':');let pref={[key]:id};if(role==='distributions'&&key==='report_id'){let r=get('reports',id);if(r)pref.project_id=r.data.project_id;}openEditor(role,'create','',pref);}
else if(action.startsWith('edit:')){let [,role,id]=action.split(':');openEditor(role,'edit',id);}
else if(action.startsWith('copy:')){let [,role,id]=action.split(':');openEditor(role,'copy',id);}
else if(action.startsWith('archive:')){let [,role,id]=action.split(':');requestArchive(role,id);}
else if(action==='cancel-archive')st.del=null;
else if(action==='review-archive'){try{confirmArchive();}catch(e){st.notice=String(e.message||e)};}
else if(action.startsWith('field:')&&st.editor){let field=action.slice(6);st.editor.draft[field]=(ev.form&&Object.prototype.hasOwnProperty.call(ev.form,field))?ev.form[field]:ev.value;}
else if(action==='save-form'&&st.editor){try{let edit=st.editor,submitted=ev.form||{};edit.draft={...edit.draft,...submitted};let op=createProposal(edit);propose([op,...parentGuard(edit,edit.draft)]);}catch(e){st.notice='Review blocked: '+String(e.message||e);}}
currentContext();
let tabs=Array.isArray(layout.tabs)?layout.tabs.filter(id=>screens.some(t=>t[0]===id)):screens.map(t=>t[0]);for(let [id]of screens)if(!tabs.includes(id))tabs.push(id);tabs=tabs.filter(id=>layout.visible?.[id]!==false);if(!tabs.length)tabs=['overview'];if(!tabs.includes(st.route)&&st.route!=='manage')st.route=tabs[0];
/* Stable order from reviewed host presentation profile. */
let navHtml=tabs.map(id=>{let t=screens.find(x=>x[0]===id),ic={overview:'◫',delivery:'▤',actions:'◇',inputs:'☷',reports:'▣'}[id];return'<button type="button" data-action="nav:'+id+'" aria-label="Open '+esc(t[1])+'" title="'+esc(t[1])+'" class="su-navitem '+(st.route===id?'on':'')+'"><span class="su-nav-icon">'+ic+'</span><span>'+esc(t[1])+'</span></button>';}).join('');
let projectSelect=all('projects').rows.map(r=>'<option value="'+esc(r.id)+'" '+(r.id===st.projectId?'selected':'')+'>'+shortText(r.data.project_code+' · '+r.data.name,60)+'</option>').join('');
let ctx=project();let sponsor=ctx?label('sponsors',ctx.data.sponsor_id):'No sponsor selected';
let top='<header class="su-topbar"><label>PROJECT <select aria-label="Selected CRO project" data-ui-state="true" data-action="scope-project" name="projectId"><option value="">Select project</option>'+projectSelect+'</select></label><label>PERIOD <input type="text" aria-label="Reporting period" data-ui-state="true" data-action="scope-period" name="period" value="'+esc(st.period)+'" placeholder="2026-11 or 2026-W44"></label><span class="su-topspacer"></span><div class="su-top-right"><span class="su-sponsor">'+esc(sponsor)+'</span>'+btn('⚙ Layout','tracker:layout','quiet')+'</div></header>';
const modal=!!(st.editor||st.detail||st.del);let body=modal?title('Record review','Close the drawer to return to the selected screen.'):st.route==='overview'?overview():st.route==='delivery'?delivery():st.route==='actions'?actionsScreen():st.route==='inputs'?inputs():st.route==='reports'?reports():manage();
let cutoffCtrl='<label class="su-cutoff">Data cutoff <input aria-label="Reporting data cutoff" data-ui-state="true" data-action="scope-date" type="date" name="asOf" value="'+esc(st.asOf)+'"></label>';
let banner=st.notice?'<div class="su-notice" role="status">'+esc(st.notice)+btn('×','dismiss-notice','icon')+'</div>':'';
if(action==='dismiss-notice')st.notice='';
let archive=st.del?'<div class="su-overlay su-center"><div class="su-dialog" role="dialog" aria-modal="true"><h2>Archive this record?</h2><p>Linked active records and approved report evidence will be checked before any reviewed change. Original version '+st.del.baseVersion+'.</p>'+(st.notice?'<p class="su-warning" role="alert">'+esc(st.notice)+'</p>':'')+'<div>'+btn('Cancel','cancel-archive','quiet')+btn('Review archive','review-archive','dangerfill')+'</div></div></div>':'';
let html='<div class="su-shell"><aside class="su-sidebar"><div class="su-brand"><b>'+esc(layout.heading||cfg.heading||'Sponsor Updates')+'</b><span>CRO sponsor reporting</span></div><nav aria-label="Application sections">'+navHtml+'</nav><div class="su-sidebar-foot"><span>Internal CRO workspace</span><small>Access controlled by TrialAgents</small></div></aside><div class="su-right">'+(modal?'':top)+'<main class="su-main"><div class="su-report-tools">'+(modal?'':cutoffCtrl)+'</div>'+banner+body+'<p class="su-boundary">Internal CRO reporting workspace · no patient-level data, automatic sponsor emails, or independent report approval.</p></main></div>'+detail()+editor()+archive+'</div>';
return{html,css:CSS,state:st};
